INSERT INTO "user_merchant" ("user_id", "merchant_name", "location", "merchant_desc", "merchant_banner_pic", "business_hours", "api_key", "create_time", "update_time") VALUES ('25f09ded-d2df-4507-8e03-200d4f307e4b', '醋坊', '贾家巷第2号', '三百年前，介休人王来福（1609-1706）以“夏伏晒、冬捞冰”的匠心，让山西老陈醋名扬天下。而其故里的张壁古堡，一群匠人循着先人的智慧，以古法为引，取山河风物为材，酿出独属这片土地的酸香——不标榜师承，却自有千年晋醋的魂。 春日的古醋坊里，陶缸静默如诗。深井水与高粱在缸中缓慢发酵，菌群随温度苏醒，将淀粉转化为酸香。这是王来福时代的智慧，也是张壁醋坊对土地的承诺：守得住时光的慢，才酿得出滋味的厚。', '', '09:00 - 22:00', '0qedmcpsXv0da3c2NYJt5u1pwduf50wx', '2026-01-06 15:14:06.108476', '2026-01-06 15:14:06.108476');
INSERT INTO "user_merchant" ("user_id", "merchant_name", "location", "merchant_desc", "merchant_banner_pic", "business_hours", "api_key", "create_time", "update_time") VALUES ('f4777ba3-160a-4194-a994-b8d080fca9a2', '茗香阁', '槐抱柳东南20米', '张壁古堡景区的桑叶茶是当地特色饮品，具有独特的品质和丰富的价值：
 原料优质：张壁古堡的桑树生长在黄土高原，汲取当地的日光与风土，其嫩叶蕴藏槲皮素、γ-氨基丁酸等活性成分，为桑叶茶提供了丰富的营养基础。
制作工艺独特：经非遗匠人改良，采用古法萎凋+定向发酵工艺，不同于传统绿茶工艺，能锁住春鲜，让桑叶褪去青涩，兼具药香与茶韵。
茶品丰富：有桑叶红茶、陈皮桑叶茶等品种。桑叶红茶呈半发酵工艺，茶汤呈蜜糖金色，入口焦甜，尾调有薄荷凉意；陈皮桑叶茶用十年新会老陈皮与北国桑叶搭配，陈皮的果香中和桑叶的微苦，清冽爽口。此外还有桑叶绿茶，口味清香，回甘绵长。
养生功效显著：桑叶茶具有疏散风热、清肺润燥、平肝明目等传统医学功效，对风热感冒、肺热咳嗽、肝阳上亢引起的视物模糊等有一定疗效。现代医学研究表明，它还能降血糖、降血脂、减肥瘦身、美容养颜、增强免疫力等。
文化内涵丰富：张壁古堡有着深厚的历史文化底蕴，桑叶茶的制作传承千年，体现了当地利用物产资源的传统，景区内的茗香阁还通过销售、兑换等方式，让游客深入体验古堡的茶文化。', '', '09:00 - 22:00', 'seNxF50fZ21jj1lfp4rerhE2rBW335H3', '2026-01-06 15:15:49.104884', '2026-01-06 15:15:49.104884');
INSERT INTO "user_merchant" ("user_id", "merchant_name", "location", "merchant_desc", "merchant_banner_pic", "business_hours", "api_key", "create_time", "update_time") VALUES ('ee179f9a-4553-4d30-926e-2507995c9489', '杏仁铺', '主街七号窑洞', '6月9日，介休张壁古堡景区主街上，44岁的武海洋正在机器旁磨杏仁粉。旁边已经打包的几十瓶杏仁粉，即将通过快递发往全国地地。一会儿有游客进店，他冲了几杯杏仁露，供游客免费品尝。“真香!味道不错!”一名游客品尝后赞道。
武海洋是介休人，18岁开始经营旅游产品，曾在介休绵山和张壁古堡搞工艺品和土特产开发，6年前在张壁古堡开了这家店。
“因为我们这里盛产杏，于是我想到了依托资源深加工纯天然杏仁粉。”武海洋说，他曾去河北承德杏仁露厂学习取经。他想，既然能做成饮料，为啥不能磨成粉呢?于是他先后开发了杏仁王、杏仁粉、杏仁片等系列产品以及酸枣糕、陈醋膏等当地特产，受到游客欢迎。武海洋说，疫情之前，他的生意不错，产品远销北上广、太原、介休等地。
吃水不忘打井人。交谈中，纯朴的武海洋反复说，他的创业成功离不开张壁古堡这个平台的支持。
记者注意到，武海洋的杏仁粉包装上印有微信码和销售电话，可以追溯食品质量。
​“杏仁粉营养价值高，保健效果显著。我相信疫情过去，旅游市场恢复后，前景肯定会更好。”武海洋说。', '', '09:00 - 22:00', 'biQqqn0FEqLjKtpfBvygspxcWYxxwEMa', '2026-01-06 15:17:54.539518', '2026-01-06 15:17:54.539518');
